\set ON_ERROR_STOP on
begin;
create schema test;
create table test.state(key text primary key,value jsonb);
grant usage on schema test to anon,authenticated;
grant select,insert,update on test.state to anon,authenticated;
create function test.ok(condition boolean,label text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function test.denied(statement text,label text) returns void language plpgsql as $$ begin begin execute statement; exception when others then raise notice 'PASS: % (rejected: %)',label,sqlerrm; return; end; raise exception 'FAIL: % was allowed',label; end $$;
grant execute on all functions in schema test to anon,authenticated;
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into public.admin_users(user_id,role) values('00000000-0000-0000-0000-000000000001','admin'),('00000000-0000-0000-0000-000000000002','teacher');
insert into test.state select 'original',to_jsonb(id) from public.classes where slug='poraque';
select test.ok((select count(*)=2 from public.classes where status='active' and slug in ('poraque','pitiu')),'migration preserves the two existing classes as active');
set local role anon;
select test.denied('select * from public.list_classes_admin()','anonymous cannot consult private class counts');
select test.denied($q$select public.create_class('Attack','attack')$q$,'anonymous cannot create classes');
select test.denied($q$update public.classes set name='Attack'$q$,'anonymous cannot directly rename classes');
select test.denied($q$select app_private.foundation_register_team(gen_random_uuid(),'X','Ana Silva','João Souza')$q$,'anonymous cannot bypass the public enrollment wrapper');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select test.denied('select * from public.list_classes_admin()','Auth account alone cannot consult class counts');
select test.denied($q$select public.create_class('Attack','attack')$q$,'Auth account alone cannot create a class');
select test.denied($q$select public.set_class_status((select (value#>>'{}')::uuid from test.state where key='original'),'archived')$q$,'Auth account alone cannot archive a class');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select test.ok((select count(*)=2 from public.list_classes_admin()),'authorized teachers may consult all classes');
select test.denied($q$select public.create_class('Attack','attack')$q$,'teacher cannot create classes');
select test.denied($q$select public.rename_class((select (value#>>'{}')::uuid from test.state where key='original'),'Changed')$q$,'teacher cannot rename classes');
select test.denied($q$select public.set_class_status((select (value#>>'{}')::uuid from test.state where key='original'),'archived')$q$,'teacher cannot archive classes');
select test.denied($q$select public.delete_class((select (value#>>'{}')::uuid from test.state where key='original'),'EXCLUIR poraque')$q$,'teacher cannot delete classes');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into test.state values('new',to_jsonb(public.create_class('Tucunaré 2027','tucunare-2027'))),('empty',to_jsonb(public.create_class('Sem vínculos','sem-vinculos')));
select test.ok((select count(*)=4 from public.classes),'new slugs beyond poraque and pitiu are accepted');
select test.ok((select count(*)=1 from public.list_classes_admin(1,1)),'class listing supports bounded pagination');
select test.denied('select * from public.list_classes_admin(-1,500)','invalid pagination rejected');
select test.denied($q$select public.create_class('Duplicada',' PORAQUE ')$q$,'normalized duplicate slug rejected');
select test.denied($q$select public.create_class('Inválida','bad/slug')$q$,'invalid slug rejected');
select test.denied($q$select public.create_class(' ','valid-slug')$q$,'blank class name rejected');
select test.denied($q$update public.classes set status='archived'$q$,'even admins cannot bypass the audited RPC with direct writes');
select public.rename_class((select (value#>>'{}')::uuid from test.state where key='original'),'Poraquê - Manhã');
select test.ok((select name='Poraquê - Manhã' and slug='poraque' and id=(select (value#>>'{}')::uuid from test.state where key='original') from public.classes where slug='poraque'),'rename preserves original UUID and slug');
select test.denied($q$select public.rename_class((select (value#>>'{}')::uuid from test.state where key='original'),' ')$q$,'blank rename rejected');
set local role anon;
insert into test.state values('team',public.register_team((select (value#>>'{}')::uuid from test.state where key='original'),'Dupla original','Ana Silva','João Souza'));
select test.ok((select value ? 'team_id' from test.state where key='team'),'active class still permits atomic permanent enrollment');
set local role authenticated;
insert into test.state values('activity',to_jsonb(public.save_assessment('Atividade histórica','',array[(select (value#>>'{}')::uuid from test.state where key='original')],'[{"prompt":"Linux?","kind":"true_false","points":10,"options":[{"label":"Verdadeiro","is_correct":true},{"label":"Falso","is_correct":false}]}]'::jsonb)));
insert into test.state select 'session',to_jsonb(id) from public.activity_sessions where activity_id=(select (value#>>'{}')::uuid from test.state where key='activity');
insert into test.state select 'answers',jsonb_agg(jsonb_build_object('question_id',q.id,'option_id',o.id)) from public.questions q join public.question_options o on o.question_id=q.id and o.is_correct where q.activity_id=(select (value#>>'{}')::uuid from test.state where key='activity');
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'published');
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'open');
set local role anon;
insert into test.state select 'attempt',public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session'));
select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'),(select value from test.state where key='answers'));
set local role authenticated;
select public.adjust_ctf(gen_random_uuid(),(select (value->>'team_id')::uuid from test.state where key='team'),7,'Evento CTF independente');
select public.set_class_status((select (value#>>'{}')::uuid from test.state where key='original'),'archived');
select test.ok((select status='archived' from public.classes where slug='poraque'),'class can be archived with its existing data intact');
select test.denied($q$select public.set_class_status((select (value#>>'{}')::uuid from test.state where key='original'),'deleted')$q$,'invalid class state rejected');
set local role anon;
select test.ok(public.register_team((select (value#>>'{}')::uuid from test.state where key='original'),'Não cadastrar','Maria Silva','José Souza') ? 'error','forged enrollment in archived class rejected by server');
select test.ok(public.login_team((select value->>'access_code' from test.state where key='team'),(select value->>'credential' from test.state where key='team'))->>'team_id'=(select value->>'team_id' from test.state where key='team'),'existing team can return after class archival without re-enrollment');
select test.ok(jsonb_array_length(public.team_history((select value->>'token' from test.state where key='team'))->'attempts')=1,'existing team history remains available after archival');
select test.ok((select status='archived' from public.classes where slug='poraque'),'sanitized class metadata stays available for historical ranking labels');
select test.denied('select * from public.team_members','archiving does not expose student names');
select test.denied('select * from public.grades','archiving does not expose private grades');
reset role;
select test.denied($q$insert into public.teams(class_id,public_name,credential_hash) values((select (value#>>'{}')::uuid from test.state where key='original'),'Privileged bypass','test-only')$q$,'database trigger also rejects privileged direct inserts in archived classes');
select test.ok((select count(*)=1 from public.teams),'failed archived enrollment creates no extra team');
select test.ok((select count(*)=2 from public.team_members),'archiving preserves exactly the original members');
select test.ok((select count(*)=1 and min(points)=10 from public.grades),'archiving preserves original grade');
select test.ok((select count(*)=1 from public.answers),'archiving preserves original answers');
select test.ok((select count(*)=1 from public.attempts),'archiving preserves original attempts');
select test.ok((select count(*)=1 and min(points)=7 from public.ctf_score_events),'archiving preserves CTF score events');
select test.ok((select points=7 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'archiving preserves public CTF score');
set local role authenticated;
select test.ok((select status='archived' and team_count=1 and attempt_count=1 and activity_count=1 and not can_delete from public.list_classes_admin() where slug='poraque'),'admin sees archived class and accurate linked counts');
select test.denied($q$select public.delete_class((select (value#>>'{}')::uuid from test.state where key='original'),'EXCLUIR poraque')$q$,'cannot delete class with teams, submissions or grades');
insert into test.state values('linked_activity',to_jsonb(public.save_assessment('Atividade vinculada','',array[(select (value#>>'{}')::uuid from test.state where key='new')],'[{"prompt":"Turma?","kind":"true_false","points":1,"options":[{"label":"Verdadeiro","is_correct":true},{"label":"Falso","is_correct":false}]}]'::jsonb)));
select test.ok((select team_count=0 and activity_count=1 and not can_delete from public.list_classes_admin() where slug='tucunare-2027'),'draft activity alone blocks class deletion');
select test.denied($q$select public.delete_class((select (value#>>'{}')::uuid from test.state where key='new'),'EXCLUIR tucunare-2027')$q$,'array-based activity association blocks deletion even without teams');
select test.ok((select can_delete from public.list_classes_admin() where slug='sem-vinculos'),'only unlinked class is eligible for deletion');
select test.denied($q$select public.delete_class((select (value#>>'{}')::uuid from test.state where key='empty'),null)$q$,'missing explicit deletion confirmation rejected');
select test.denied($q$select public.delete_class((select (value#>>'{}')::uuid from test.state where key='empty'),'EXCLUIR outra')$q$,'incorrect typed deletion confirmation rejected');
select public.delete_class((select (value#>>'{}')::uuid from test.state where key='empty'),'EXCLUIR sem-vinculos');
select test.ok(not exists(select 1 from public.classes where slug='sem-vinculos'),'confirmed unlinked class deletion succeeds');
select test.ok((select count(*)=1 from public.grades),'explicit empty-class deletion never deletes existing grades');
select public.set_class_status((select (value#>>'{}')::uuid from test.state where key='original'),'active');
set local role anon;
select test.ok(public.register_team((select (value#>>'{}')::uuid from test.state where key='original'),'Nova dupla','Maria Silva','José Souza') ? 'team_id','reactivated class accepts new teams again');
set local role authenticated;
select test.ok((select count(distinct action)=5 from public.audit_events where action in ('create_class','rename_class','archive_class','reactivate_class','delete_class')),'all five class management operations are audited');
select test.ok(exists(select 1 from public.audit_events where action='delete_class' and target_id=(select (value#>>'{}')::uuid from test.state where key='empty') and details->>'slug'='sem-vinculos'),'deleted class UUID and public metadata remain in audit');
select test.ok(not exists(select 1 from public.audit_events where action like '%class%' and actor_id is distinct from '00000000-0000-0000-0000-000000000001'::uuid),'audit records the explicitly authorized administrator');
set constraints all immediate;
rollback;
